export function behaviorNames(html: string): string[] {
  const candidates = [
    "modal",
    "tabs",
    "tooltip",
    "close-button",
    "in-place-edit",
    "drawer-layout",
    "tree-browser",
    "form-field",
    "menu",
  ];
  return candidates.filter((name) =>
    new RegExp(`class="[^"]*\\binstui-${name}\\b`, "u").test(html),
  );
}

