/**
 * @component pagination.page
 * @memberOf pagination
 * @selector .page
 * @a11y Mark the current page with `aria-current="page"`, give each page an accessible name that includes the page number, and wrap the set in a `<nav>` with an `aria-label`.
 * @summary A page link or button (InstUI `Pagination.Page`); the current page carries `[aria-current]`.
 * @modifier -current — The current page; same styling as `[aria-current]`.
 * @cssstate current
 * @structure
 * @component pagination {
 *   .page {}
 * }
 * @example -automatica11y
 * ```html
 * <nav class="pfx-pagination" aria-label="Pagination">
 *   <button class="arrow" type="button" aria-label="First page" disabled><span class="pfx-icon -icon-chevrons-left"></span></button>
 *   <button class="arrow" type="button" aria-label="Previous page" disabled><span class="pfx-icon -icon-chevron-left"></span></button>
 *   <a class="page" href="#" aria-current="page">1</a>
 *   <a class="page" href="#">2</a>
 *   <a class="page" href="#">3</a>
 *   <span class="ellipsis">…</span>
 *   <a class="page" href="#">12</a>
 *   <a class="arrow" href="#" aria-label="Next page"><span class="pfx-icon -icon-chevron-right"></span></a>
 *   <a class="arrow" href="#" aria-label="Last page"><span class="pfx-icon -icon-chevrons-right"></span></a>
 * </nav>
 * ```
 */
@scope (.pfx-pagination) {
  :scope {
    /* A page number — an <a> or <button>. Text-style primary button: brand text, no fill. */
    > .page {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-inline-size: 2rem;
      min-block-size: 2rem;
      padding: var(--instui-spacing-space2xs) var(--instui-spacing-space-xs);
      color: var(--instui-color-text-interactive-navigation-primary-base);
      background: transparent;
      border: var(--instui-border-width-md) solid transparent;
      border-radius: var(--instui-component-base-button-border-radius);
      font: inherit;
      font-weight: var(--instui-font-weight-interactive);
      text-decoration: none;
      cursor: pointer;
    }

    > .page:hover {
      background: var(--instui-color-background-muted);
      color: var(--instui-color-text-interactive-navigation-primary-hover);
    }

    /* The current page — a filled primary button (InstUI: color="primary" withBackground withBorder). */
    > .page[aria-current],
    > .page.-current {
      background: var(--instui-color-background-interactive-action-primary-base);
      color: var(--instui-color-text-interactive-action-primary-base);
      border-color: var(--instui-color-background-interactive-action-primary-base);
    }

    > .page[aria-current]:hover,
    > .page.-current:hover {
      background: var(--instui-color-background-interactive-action-primary-hover);
      border-color: var(--instui-color-background-interactive-action-primary-hover);
      color: var(--instui-color-text-interactive-action-primary-base);
    }
  }
}

