    ...metadata,
    configurations: 0,
    tiers: {},
    axe: { violations: 0, reviews: 0, reviewRules: {}, violationRules: {} },
    ibm: { violations: 0, reviews: 0, reviewRules: {}, violationRules: {} },
    checks: {},
    flags: 0,
    findings: [],
  };
