  const entries = [{ name: "agent-shell", kind: "component" }];
  annotateAccessibility(entries, [page], snapshot);
  const first = readFileSync(page, "utf8");
  expect(first).toContain("Not audited");
  expect(first).not.toContain("| axe-core |");
