/* Home styles */

:root:has(.is-home) {
  /* Fallback paint for any area outside body during initial layout. */
  background-color: var(--vp-home-bg-color, #002b4d);
}

.is-home {
  /* VitePress sets body background-color from --vp-c-bg in a base layer.
     Override the token on home so that layered rule resolves transparent. */
  --vp-c-bg: transparent;
  position: relative;
  min-height: 100vh;
  background-color: transparent;
}

.is-home::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--vp-home-bg-image);
  background-repeat: no-repeat;
  background-size: cover;
  background-position: right bottom;
  pointer-events: none;
}

html[dir="rtl"] .is-home::before {
  transform: scaleX(-1);
}

.VPNavBar.home {
  background-color: var(--vp-nav-bg-color);
}

/* In RTL layouts, navbar flyouts (language dropdown, extra/theme picker, etc.) sit on the left side
   of the header. VitePress defaults flyout menus to `right: 0`, which aligns their right edge to the
   icon and causes the menu to overflow off the left edge of the page. Align to the left rail instead. */
html[dir="rtl"] .VPFlyout .menu {
  right: auto;
  left: 0;
}

@media (min-width: 768px) {
  html[dir="rtl"] .VPNavBarSearch {
    padding-right: 24px;
    padding-left: 0;
  }
}

@media (min-width: 960px) {
  html[dir="rtl"] .VPNavBarSearch {
    padding-right: 32px;
    padding-left: 0;
  }

  html[dir="rtl"] .VPSidebar {
    right: 0;
    left: auto;
  }

  html[dir="rtl"] .VPContent.has-sidebar {
    padding-right: var(--vp-sidebar-width);
    padding-left: 0;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .title {
    right: 0;
    left: auto;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .content {
    padding-right: var(--vp-sidebar-width);
    padding-left: 32px;
  }

  html[dir="rtl"] .VPNavBar:not(.home.top) .content-body {
    margin-right: 0;
    margin-left: -100vw;
    padding-right: 0;
    padding-left: 100vw;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .divider {
    padding-right: var(--vp-sidebar-width);
    padding-left: 0;
  }
}

@media (min-width: 1280px) {
  html[dir="rtl"] .VPDoc .aside {
    order: 2;
    padding-right: 32px;
    padding-left: 0;
  }

  html[dir="rtl"] .VPDoc .content {
    order: 1;
  }

  html[dir="rtl"] .VPNavBar .content-body .social-links {
    margin-right: 0;
    margin-left: -8px;
  }
}

@media (min-width: 1440px) {
  html[dir="rtl"] .VPSidebar {
    padding-right: max(32px, calc((100% - (var(--vp-layout-max-width) - 64px)) / 2));
    padding-left: 32px;
  }

  html[dir="rtl"] .VPContent.has-sidebar {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: calc((100% - var(--vp-layout-max-width)) / 2);
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .title {
    padding-right: max(32px, calc((100% - (var(--vp-layout-max-width) - 64px)) / 2));
    padding-left: 32px;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .content {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: calc((100% - var(--vp-layout-max-width)) / 2 + 32px);
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .divider {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: 0;
  }
}

/* Class names like `.--bg-<name>` are all bidi-neutral characters, so in an RTL paragraph the bidi
   algorithm gives them the paragraph direction and reorders them on screen. Isolate code as LTR. */
html[dir="rtl"] .vp-doc :is(code, kbd, samp) {
  direction: ltr;
  unicode-bidi: isolate;
}

html[dir="rtl"] .vp-doc div[class*="language-"] :is(pre, code) {
  direction: ltr;
  text-align: left;
}

/* Shared popover chrome for the home hero: both the terminal's package-manager popover
   (CommandCycleRow.vue's `.gs-command-row__popover`) and the platform picker below apply this
   class, so there's one visual treatment instead of two — the hero is on-color in every site
   theme, but that's `light-dark()`'d here exactly like the terminal's own popover already was. */
.hero-popover {
  display: flex;
  flex-direction: column;
  min-inline-size: 10rem;
  padding: 4px;
  border: 1px solid var(--vp-c-divider);
  border-radius: 6px;
  background: light-dark(
    var(--instui-color-background-container),
    var(--instui-color-background-page)
  );
  box-shadow: 0 2px 8px rgb(0 0 0 / 26%);
}

.hero-popover button {
  padding: 4px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
  /* Without this, the browser's default focus/active ring (which picks up `currentColor`, i.e.
     each item's brand color) flashes briefly on mouseleave between hover and focus-visible states. */
  outline: none;
}

.hero-popover button:hover,
.hero-popover button:focus-visible {
  background: light-dark(#e9edf3, #2a3038);
  outline: none;
}

.VPHomeHero {
  .heading {
    color: var(--instui-primitive-color-white);

    & :is(.name, .clip) {
      color: var(--vp-home-hero-name-color, var(--instui-primitive-color-blue-blue50));
      -webkit-text-fill-color: var(
        --vp-home-hero-name-color,
        var(--instui-primitive-color-blue-blue50)
      );
    }
  }

  .tagline {
    /* color: #aab0b5; */
    display: none;
  }

  .platform {
    position: relative;
    display: inline-flex;
    align-items: center;
    background-color: color-mix(
      in srgb,
      var(--instui-color-institutional-brand-primary) 50%,
      transparent
    );
    box-shadow: inset 0 -4px 0 0
      color-mix(in srgb, var(--instui-color-institutional-brand-primary) 75%, transparent);
    padding: 0 0.25rem;
    border-radius: var(--instui-primitive-size-size4);
    cursor: pointer;
  }

  .platform:hover {
    box-shadow:
      inset 0 -4px 0 0
        color-mix(in srgb, var(--instui-color-institutional-brand-primary) 75%, transparent),
      0 0 0 2px rgba(255, 255, 255, 0.5);
  }

  /* Keyboard-focus-only affordance hinting the pill opens a picker — collapsed to zero width
     otherwise, so it never nudges the pill's layout or shows on mouse hover. */
  .platform-picker__chevron {
    display: inline-block;
    inline-size: 0;
    block-size: 0.5em;
    margin-inline-start: 0;
    overflow: hidden;
    opacity: 0;
    border-inline-end: 2px solid currentColor;
    border-block-end: 2px solid currentColor;
    transform: rotate(45deg) translateY(-2px);
    transition:
      opacity 0.15s ease,
      inline-size 0.15s ease,
      margin-inline-start 0.15s ease;
  }

  .platform:focus-visible .platform-picker__chevron {
    inline-size: 0.5em;
    margin-inline-start: 0.3em;
    opacity: 0.8;
  }

  /* Position/sizing/grouping only — visual chrome (background, border, shadow, button hover) comes
     from the shared `.hero-popover` class above. */
  .platform-picker__menu {
    position: absolute;
    inset-block-start: calc(100% + 8px);
    inset-inline-start: 0;
    z-index: 20;
    display: none;
    gap: 2px;
    min-inline-size: 12rem;
    max-block-size: 22rem;
    overflow-y: auto;
    font-size: 0.85rem;
    font-weight: 400;
    /* `.heading`/`.text` set a fixed-px line-height (40-64px across breakpoints); that's an
       inherited absolute length, so it doesn't shrink with the smaller font-size above and would
       otherwise make every row enormous. */
    line-height: 1.3;
    text-transform: none;
    letter-spacing: normal;
    cursor: auto;
  }

  .platform-picker__menu.-open {
    display: flex;
  }

  .platform-picker__group-title {
    padding: 2px 6px;
    color: var(--vp-c-text-2);
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .platform-picker__menu [role="group"] {
    display: flex;
    flex-direction: column;
  }

  .platform-picker__menu button {
    display: flex;
    align-items: center;
    gap: 0.4em;
    padding: 3px 6px;
  }

  .platform-picker__icon {
    display: inline-block;
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
    mask: var(--pantoken-glyph) center / contain no-repeat;
  }

  /* Keeps the animated platform label on one line even when the roller swaps in a long label like
      "WordPress". */
  .platform-line {
    white-space: nowrap;
  }

  /* "accessible WordPress" is close to the line's available width on narrow phones; shrink slightly
     so it doesn't spill past the hero's edge padding. */
  @media (max-width: 639px) {
    .platform-line {
      font-size: 0.85em;
    }
  }

  /* Text roller built by VPHomeHero.vue's platform cycle: a fixed-height clipping window holding one
     or two absolutely positioned `.platform-label`s, so the outgoing label can slide down out of
     view while the incoming one slides up into its place. `.platform`'s own width is auto and
     tracks the viewport's animated width every frame, since inline-block children size their
     container just like plain text would. */
  .platform-viewport {
    position: relative;
    display: inline-block;
    overflow: hidden;
    height: 1.2em;
    transition: width 0.45s ease;
  }

  .platform-label {
    position: absolute;
    inset-inline-start: 0;
    top: 0;
    display: inline-block;
    white-space: nowrap;
    transition: transform 0.45s ease;
  }

  /* Same roller technique as `.platform-viewport`/`.platform-label`, but for the brand glyph:
     `--pantoken-glyph` is set inline per glyph element (not via a platform class) so the outgoing
     and incoming glyphs can each keep their own icon while they slide past one another.
     Named `.platform-glyph*`, not `.platform-icon*` — any class containing the substring
     "-icon-" gets painted by the design system's generic `[class*="-icon-"]::before` painter,
     which would render a second, broken glyph on top of this one. */
  .platform-glyph-viewport {
    position: relative;
    display: inline-block;
    overflow: hidden;
    inline-size: 0.75em;
    block-size: 0.75em;
    margin-inline-end: 0.0625em;
    margin-bottom: 0.125em;
  }

  .platform-glyph {
    position: absolute;
    inset-inline-start: 0;
    top: 0;
    inline-size: 100%;
    block-size: 100%;
    background: currentColor;
    -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
    mask: var(--pantoken-glyph) center / contain no-repeat;
    transition: transform 0.45s ease;
  }
}

.VPHomeFeatures .box:has(.VPImage) {
  grid-template-columns: 1.25rem 1fr;
  align-items: start;
  gap: 0.5rem 0.75rem;
  display: grid;

  .VPImage {
    grid-area: 1/1;
    width: 1.25rem;
    margin: 0;
  }

  .details {
    grid-column: 1/-1;
    margin: 0;

    :not(pre) > code {
      color: var(--vp-code-color);
      background: var(--vp-code-bg);
      border-radius: 4px;
      padding: 3px 6px;
      font-size: var(--vp-code-font-size);
    }

    a {
      color: var(--instui-color-text-interactive-navigation-primary-base);
      text-decoration: underline;

      &:hover,
      &:focus-visible,
      &:active {
        color: var(--instui-color-text-interactive-navigation-primary-hover);
      }
    }
  }
}

.vitepress-sidebar-toggle {
  margin-inline-start: 2rem;
}

/* The light/dark toggle now lives inside ThemeColorPicker (desktop dropdown, tablet kebab, mobile
   accordion) so it travels with the theme/color choice — hide VitePress's standalone copies.
   `!important` because VitePress's own scoped style (with its `[data-v-*]` attribute selector) 
   otherwise outweighs our plain class selector. */
.VPNavBarAppearance,
.VPNavScreenAppearance {
  display: none !important;
}

/* Keep custom outline social icons from inheriting VitePress's solid icon fill. */
.VPSocialLink > svg {
  fill: none !important;
}

/* VitePress rounds and scrolls `.VPMenu` on the same box; the translations flyout lists 40+ locales,
   so its native scrollbar routinely squares off the corners it touches. Move the radius + shadow to
   the flyout's outer `.menu` wrapper and clip through `overflow: hidden` there instead, leaving
   `.VPMenu` to scroll unconstrained by rounding. */
.VPNavBarTranslations .menu {
  overflow: hidden;
  border-radius: 12px;
  box-shadow: var(--vp-shadow-3);
  border: 1px solid var(--vp-c-divider);
}

.VPNavBarTranslations .menu .VPMenu {
  border-radius: 0;
  box-shadow: none;
  border: 0 none;
}

@media (min-width: 768px) {
  .VPNavBarTranslations .menu,
  .VPNavBarTranslations .menu .VPMenu {
    max-height: 50vh;
  }

  .VPNavBarSearchButton.VPNavBarSearchButton {
    background-color: light-dark(var(--instui-primitive-color-grey-grey10), var(--vp-c-bg-alt));
  }
}

@media (min-width: 960px) {
  .VPNavBarTitle.has-sidebar .title {
    --vp-c-divider: transparent;
  }
}

.custom-block {
  border-width: 2px;
  box-shadow: var(--instui-elevation-above);

  &.tip {
    background-color: transparent;
    border-color: var(--vp-custom-block-tip-bg);

    code {
      background: transparent;
    }
  }

  &.warning {
    background-color: transparent;
    border-color: var(--vp-custom-block-warning-bg);

    code {
      background: transparent;
    }
  }

  &.info {
    background-color: transparent;
    border-color: var(--vp-custom-block-info-bg);

    code {
      background: transparent;
    }
  }

  &.danger {
    background-color: transparent;
    border-color: var(--vp-custom-block-danger-bg);

    code {
      background: transparent;
    }
  }
}

