  ar: "ar",
  el: "el",
  fa: "fa",
  he: "he",
  hi: "hi",
  hy: "hy",
  ja: "jp",
  ko: "ko",
  ru: "ru",
  th: "th",
  uk: "uk",
  "zh-Hans": "zh",
  "zh-Hant": "zh",
};

