      .flatMap((detail) => detail.criteria);
    const heading = `<span class="pantoken-a11y-check">${cell(name)}</span>${
      criteria.length
        ? `<span class="pantoken-a11y-criteria">WCAG 2.2 ${[...new Set(criteria)].map(cell).join(", ")}</span>`
        : ""
