  expect(snapshot.records.constructor).toHaveLength(1);
  expect(Object.values(snapshot.records)[0]![0]!.axe.reviewRules.__proto__).toBe(1);
  expect(accessibilitySection("toString", snapshot)).toContain("Not audited");
