    lines.push(`> ${cell(warning)}`, "");
  for (const tier of TIERS) {
    const names = [
      ...new Set(
        rows.flatMap((row) => row.details.filter((d) => d.tier === tier).map((d) => d.name)),
      ),
    ].sort();
    if (!names.length) continue;
    lines.push(...tierTable(tier, tierLabel(tier), names, rows));
  }
