  expect(() => importAccessibilityRun(input.directory)).toThrow("inventory");
  input.coverage.evidence[0]!.expected.pop();
  input.results.targets[0]!.archetypes.page!.configs[0]!.tiers.rules.engines.axe.status = "failed";
