  --pantoken-logo-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27-62.159%20-114.512%20506.020%20160.333%27%3E%3Ccircle%20cx%3D%27-39.311%27%20cy%3D%2712.737%27%20r%3D%2718.849%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E");
  --pantoken-logo-aspect: 3.156056;
}

html[lang="he"] .VPNavBarTitle .title {
  --pantoken-logo-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27-37.439%20-86.680%20459.363%20123.139%27%3E%3Ccircle%20cx%3D%27-19.367%27%20cy%3D%2718.387%27%20r%3D%2714.072%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E");
  --pantoken-logo-aspect: 3.730443;
