   directory: string;
   expected: string[];
   completed: string[];
   error?: string;
   gaps?: number;
   coverage?: AuditCoverage;
 }

 /** Per-state tier execution and diagnostic notices, separate from engine findings. */
 export interface AuditCoverage {
   notices: string[];
   configurations: {
     target: string;
     archetype: string;
     index: number;
     state: string;
     tiers: Record<string, string>;
