          },
          { state: "open", tiers: { rules: { status: "ran" }, vsr: { status: "ran" } } },
        ],
      },
    },
    summary: { gaps: [], notTestable: [] },
  }));
  const coverage = targets.flatMap(({ id }) =>
    ["interactions", "computed", "conditions"].map(
      (tier) => `${id}/dialog/1/${tier}: missing requested tier`,
