const entry = (
  example = '-automatica11y\n```html\n<button class="pfx-button">Save</button>\n```',
) =>
  parseCssDocs(
    `/**\n * @component button\n * @example ${example.replaceAll("\n", "\n * ")}\n */\n.pfx-button { color: red; }`,
  );

