test("writes a coverage index with separate errors and the automated-coverage caveat", async () => {
  const out = temp();
  writeIndex(
    out,
    [{ directory: "sample", expected: ["a"], completed: [], error: "missing | target" }],
    [],
  );
  const markdown = readFileSync(join(out, "index.md"), "utf8");
